        IF EStop OR Level >= LVL_HIGH THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;
    2: // Heat
        IF EStop OR Temp >= TEMP_SET THEN
            State := 3;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
