    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: -- Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
    2: -- Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
    3: -- React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF TON(PT_REACT).Q THEN
            State := 4;
        END_IF;
    4: -- Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

-- Safety checks
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;
IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;
IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    TFill : TON;
    THeat : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level > LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        TFill(IN := TRUE, PT := T#1s);
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
            TFill(IN := FALSE);
        END_IF;
    2: // Heat
        THeat(IN := TRUE, PT := T#1s);
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
            THeat(IN := FALSE);
        END_IF;
    3: // React
        THeat(IN := TRUE, PT := T#1s);
        Heater := TRUE;
        Agitator := TRUE;
        IF THeat.Q THEN
            State := 4;
            THeat(IN := FALSE);
        END_IF;
    4: // Drain
        TFill(IN := TRUE, PT := T#1s);
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
            TFill(IN := FALSE);
        END_IF;
END_CASE;

IF State <> 1 AND State <> 4 THEN
    FillValve := FALSE;
END_IF;

IF State <> 2 AND State <> 3 THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF State <> 4 THEN
    DrainValve := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
    State := 3;
ELSIF State = 3 AND T#3s <= PT_REACT THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    Count := MIN(Count + 1, CAP);
END_IF;

IF ExitSensor AND NOT PrevExit THEN
    Count := MAX(Count - 1, 0);
END_IF;

FullSign := Count = CAP;
EntryBarrierOpen := EntryReq AND NOT FullSign;

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

END_PROGRAM

