PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;

    1: // Star
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF T#0s > PT_STAR THEN
            State := 2;
        END_IF;
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;

    2: // Delta
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
END_CASE;

END_PROGRAM

