PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1: // Pre-purge
        IF NOT PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := T#2s);
        ELSE
            Fan := TRUE;
            Fuel := FALSE;
            Ignition := FALSE;
        END_IF;

    2: // Ignition trial
        IF NOT IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
                Fan := TRUE;
                Fuel := TRUE;
                Ignition := FALSE;
            ELSE
                State := 0;
            END_IF;
        ELSE
            Fan := TRUE;
            Fuel := TRUE;
            Ignition := TRUE;
        END_IF;

    3: // Run
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        ELSE
            Fan := TRUE;
            Fuel := TRUE;
            Ignition := FALSE;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
END_IF;

IF State <> 1 THEN
    PurgeTimer(IN := FALSE);
END_IF;

IF State <> 2 THEN
    IgnitionTimer(IN := FALSE);
END_IF;

Fan := (State >= 1) AND (State <= 3);
Fuel := (State = 3);
Ignition := (State = 3) AND Flame;

END_PROGRAM

